items.text:
body {
    font-family: var(--body-font, Arial, Helvetica, sans-serif);
    color: var(--body-text-color, #1f2937);
}

.blog-page-title,
.blog-page-title a {
    font-family: var(--blog-title-font, Georgia, "Times New Roman", serif);
    color: var(--blog-title-color, #3f3128) !important;
    font-size: var(--blog-title-size, 32px);
    line-height: 1.08;
}

.blog-page-subtitle {
    margin: 10px 0 0;
    max-width: 760px;
    font-size: clamp(0.95rem, 0.9rem + 0.22vw, 1.12rem);
    line-height: 1.45;
    color: var(--blog-title-color, #3f3128) !important;
    opacity: 0.82;
}

.calendar-title--nav,
.calendar-month-nav {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    flex-wrap: wrap;
    row-gap: 8px;
}

.calendar-title--nav > span,
.calendar-month-nav > span {
    flex: 1;
    text-align: center;
}

.calendar-title--nav::after,
.calendar-month-nav::after {
    flex: 0 0 100%;
    width: 85%;
    margin: 0 auto;
}

.calendar-month-nav-link {
    width: 30px;
    height: 30px;
    min-width: 30px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    text-decoration: none;
    font-size: 20px;
    line-height: 1;
    font-weight: 600;
    color: inherit;
    background: rgba(255,255,255,0.26);
    border: 1px solid rgba(255,255,255,0.35);
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    transition: transform 0.18s ease, background-color 0.18s ease, border-color 0.18s ease, opacity 0.18s ease;
}

.calendar-month-nav-link:hover {
    transform: translateY(-1px);
    background: rgba(255,255,255,0.38);
    border-color: rgba(255,255,255,0.55);
    color: inherit;
}

.blog-post-entry h4,
.blog-post-title {
    font-family: var(--post-title-font, Georgia, "Times New Roman", serif) !important;
    color: var(--post-title-color, #111827) !important;
    font-size: var(--post-title-size, 24px) !important;
    line-height: 1.18;
}

.calendar-title,
.archive-title,
.sidebar-box-title,
.blog-box-title {
    font-family: var(--box-title-font, Georgia, "Times New Roman", serif) !important;
    color: var(--box-title-color, #3f3128) !important;
    font-size: var(--box-title-size, 13px) !important;
    line-height: 1.18;
}


.comment-item {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    width: 100%;
    max-width: 100%;
}

.comment-avatar {
    width: 42px;
    height: 42px;
    min-width: 42px;
    flex: 0 0 42px;
    border-radius: 50%;
    object-fit: cover;
    display: block;
    align-self: flex-start;
}

.comment-body {
    flex: 1 1 auto;
    min-width: 0;
    max-width: 100%;
}

.comment-header {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 6px 10px;
    max-width: 100%;
}

.comment-author,
.comment-author a {
    overflow-wrap: anywhere;
    word-break: break-word;
}

.comment-text {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    word-break: break-word;
    line-break: anywhere;
}

.comment-row {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    max-width: 520px;
}

.comment-row textarea {
    flex: 1 1 auto;
    min-width: 0;
}

@media (max-width: 576px) {
    .comment-item {
        gap: 10px;
    }

    .comment-avatar {
        width: 38px;
        height: 38px;
        min-width: 38px;
        flex-basis: 38px;
    }

    .comment-row {
        flex-direction: column;
        align-items: stretch;
        max-width: 100%;
    }

    .comment-row .btn,
    .comment-row button {
        align-self: flex-start;
    }
}

/* BLOGPLATFORM_SHARED_BANNER_POSITION_SIZE_FIX_START */
.blog-banner-strip {
    width: 100%;
}

.blog-banner-row {
    display: flex;
    width: 100%;
}

.blog-banner-pos-left {
    justify-content: flex-start;
}

.blog-banner-pos-center {
    justify-content: center;
}

.blog-banner-pos-right {
    justify-content: flex-end;
}

.blog-banner-row .blog-banner {
    width: 100%;
}

.blog-banner-size-xsmall .blog-banner {
    max-width: 280px;
}

.blog-banner-size-small .blog-banner {
    max-width: 480px;
}

.blog-banner-size-medium .blog-banner {
    max-width: 760px;
}

.blog-banner-size-large .blog-banner {
    max-width: 980px;
}

.blog-banner-size-full_width .blog-banner {
    max-width: 100%;
}

.blog-banner-img {
    display: block;
    width: 100%;
    max-width: 100%;
}
