    font-family: var(--box-title-font, Georgia, "Times New Roman", serif) !important;
    color: var(--box-title-color, #3f3128) !important;
    font-size: var(--box-title-size, 13px) !important;
    line-height: 1.18;
}


.comment-item {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    width: 100%;
    max-width: 100%;
}

.comment-avatar {
    width: 42px;
    height: 42px;
    min-width: 42px;
    flex: 0 0 42px;
    border-radius: 50%;
    object-fit: cover;
    display: block;
    align-self: flex-start;
}

.comment-body {
    flex: 1 1 auto;
    min-width: 0;
    max-width: 100%;
}

.comment-header {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 6px 10px;
    max-width: 100%;
}

.comment-author,
.comment-author a {
    overflow-wrap: anywhere;
    word-break: break-word;
}

.comment-text {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    word-break: break-word;
    line-break: anywhere;
}

.comment-row {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    max-width: 520px;
}

.comment-row textarea {
    flex: 1 1 auto;
    min-width: 0;
}

@media (max-width: 576px) {
    .comment-item {
        gap: 10px;
    }

    .comment-avatar {
        width: 38px;
        height: 38px;
        min-width: 38px;
        flex-basis: 38px;
    }

    .comment-row {
        flex-direction: column;
        align-items: stretch;
        max-width: 100%;
    }

    .comment-row .btn,
    .comment-row button {
        align-self: flex-start;
    }
}

