(function () {
    const searchUrl = "/mentions/search/";
    let activeTextarea = null;
    let activeStart = null;
    let activeEnd = null;
    let results = [];
    let selectedIndex = 0;

    const box = document.createElement("div");
    box.className = "bp-mention-box";
    document.body.appendChild(box);

    function getMentionInfo(textarea) {
        const cursor = textarea.selectionStart;
        const textBeforeCursor = textarea.value.slice(0, cursor);
        const match = textBeforeCursor.match(/(^|\s)@([A-Za-z0-9_.+-]{0,40})$/);

        if (!match) {
            return null;
        }

        const query = match[2] || "";
        const start = cursor - query.length - 1;

        return {
            query: query,
            start: start,
            end: cursor
        };
    }

    function positionBox(textarea) {
        const rect = textarea.getBoundingClientRect();
        box.style.left = (window.scrollX + rect.left) + "px";
        box.style.top = (window.scrollY + rect.bottom + 6) + "px";
        box.style.width = Math.min(rect.width, 320) + "px";
    }

    function hideBox() {
        box.style.display = "none";
        box.innerHTML = "";
        activeTextarea = null;
        activeStart = null;
        activeEnd = null;
        results = [];
        selectedIndex = 0;
    }

    function insertMention(user) {
        if (!activeTextarea || activeStart === null || activeEnd === null) {
            return;
        }

        const before = activeTextarea.value.slice(0, activeStart);
        const after = activeTextarea.value.slice(activeEnd);
        const mention = "@" + user.username + " ";

        activeTextarea.value = before + mention + after;

        const newCursor = (before + mention).length;
        activeTextarea.focus();
        activeTextarea.setSelectionRange(newCursor, newCursor);

        hideBox();
    }

    function renderResults() {
        box.innerHTML = "";

        if (!results.length) {
            box.style.display = "none";
            return;
        }

        results.forEach(function (user, index) {
            const button = document.createElement("button");
            button.type = "button";
            button.className = "bp-mention-item" + (index === selectedIndex ? " active" : "");
            button.innerHTML = '<span class="bp-mention-username">@' + user.username + '</span>';

            if (user.label && user.label !== user.username) {
                button.innerHTML += '<br><small>' + user.label + '</small>';
            }

            button.addEventListener("mousedown", function (event) {
                event.preventDefault();
                insertMention(user);
            });

            box.appendChild(button);
        });

        box.style.display = "block";
    }

    async function searchUsers(textarea) {
        const info = getMentionInfo(textarea);

        if (!info) {
            hideBox();
            return;
        }

        activeTextarea = textarea;
        activeStart = info.start;
        activeEnd = info.end;

        positionBox(textarea);

        try {
            const response = await fetch(searchUrl + "?q=" + encodeURIComponent(info.query), {
                headers: {
                    "X-Requested-With": "XMLHttpRequest"
                }
            });

            if (!response.ok) {
                hideBox();
                return;
            }

            const data = await response.json();
            results = data.results || [];
            selectedIndex = 0;
            renderResults();
        } catch (error) {
            hideBox();
        }
    }

    document.addEventListener("input", function (event) {
        const textarea = event.target;

        if (!textarea || textarea.tagName !== "TEXTAREA" || textarea.name !== "content") {
            return;
        }

        searchUsers(textarea);
    });

    document.addEventListener("keydown", function (event) {
        if (box.style.display !== "block" || !activeTextarea) {
            return;
        }

        if (event.key === "ArrowDown") {
            event.preventDefault();
            selectedIndex = Math.min(selectedIndex + 1, results.length - 1);
            renderResults();
        }

        if (event.key === "ArrowUp") {
            event.preventDefault();
            selectedIndex = Math.max(selectedIndex - 1, 0);
            renderResults();
        }

        if (event.key === "Enter" && results.length) {
            event.preventDefault();
            insertMention(results[selectedIndex]);
        }

        if (event.key === "Escape") {
            hideBox();
        }
    });

    document.addEventListener("click", function (event) {
        if (!box.contains(event.target)) {
            hideBox();
        }
    });
})();


