    document.addEventListener('click', function (event) {
      const toggleButton = event.target.closest('[data-edit-comment-toggle]');
      const cancelButton = event.target.closest('[data-edit-comment-cancel]');

      if (toggleButton) {
        event.preventDefault();
        const commentId = toggleButton.getAttribute('data-edit-comment-toggle');
        const textBox = document.querySelector('[data-comment-text="' + commentId + '"]');
        const editForm = document.querySelector('[data-edit-comment-form="' + commentId + '"]');

        if (textBox && editForm) {
          textBox.classList.add('d-none');
          editForm.classList.remove('d-none');
          const textarea = editForm.querySelector('textarea[name="content"]');
          if (textarea) {
            textarea.focus();
            textarea.setSelectionRange(textarea.value.length, textarea.value.length);
          }
        }
      }

      if (cancelButton) {
        event.preventDefault();
        const commentId = cancelButton.getAttribute('data-edit-comment-cancel');
        const textBox = document.querySelector('[data-comment-text="' + commentId + '"]');
        const editForm = document.querySelector('[data-edit-comment-form="' + commentId + '"]');

        if (textBox && editForm) {
          editForm.classList.add('d-none');
          textBox.classList.remove('d-none');
        }
      }
    });
  });




