/* PREMIUM BLOG TITLE SHIMMER EFFECT */
.blog-page-title.premium-blog-title-effect{
    position: relative !important;
    display: inline-block !important;
    isolation: isolate !important;
    overflow: visible !important;
    text-shadow:
        0 0 7px rgba(138, 53, 255, 0.22),
        0 0 12px rgba(255, 211, 77, 0.14);
}

.blog-page-title.premium-blog-title-effect::before{
    content: "";
    position: absolute;
    inset: -4px -10px;
    border-radius: 14px;
    background: linear-gradient(120deg,
        transparent 0%,
        rgba(255,255,255,0.00) 36%,
        rgba(255,255,255,0.30) 50%,
        rgba(255,255,255,0.00) 64%,
        transparent 100%);
    transform: translateX(-120%);
    animation: premiumTitleShimmer 4.8s ease-in-out infinite;
    pointer-events: none;
    z-index: 2;
    mix-blend-mode: screen;
}

.blog-page-title.premium-blog-title-effect::after{
    content: "";
    position: absolute;
    inset: -8px -14px;
    border-radius: 18px;
    background: linear-gradient(135deg,
        rgba(138, 53, 255, 0.20),
        rgba(216, 92, 255, 0.14),
        rgba(255, 211, 77, 0.18));
    filter: blur(14px);
    opacity: 0.42;
    z-index: -1;
    pointer-events: none;
}

@keyframes premiumTitleShimmer{
    0%{ transform: translateX(-120%); opacity: 0; }
    12%{ opacity: 1; }
    38%{ transform: translateX(120%); opacity: 0.85; }
    55%{ opacity: 0; }
    100%{ transform: translateX(120%); opacity: 0; }
}

.premium-title-crown{
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-left: 7px;
    width: 0.72em;
    height: 0.72em;
    color: #ffd34d;
    vertical-align: super;
    transform: translateY(-0.12em);
    filter:
        drop-shadow(0 0 3px rgba(255, 211, 77, 0.55))
        drop-shadow(0 0 6px rgba(138, 53, 255, 0.18));
}

.premium-title-crown svg{
    width: 100%;
    height: 100%;
    fill: currentColor;
    display: block;
}




